public class DigitalRoot {

    public static int digitalRoot(int n) {
        while (n >= 10) {
            int sum = 0;
            int remaining = n;
            while (remaining > 0) {
                sum += remaining % 10;
                remaining = remaining / 10;
            }
            n = sum;
        }
        return n;
    }
}
